import('file:///D:/develop/works/tombo-view-ask-policy/dist/index.js').then(async sdk => {
  const fs = await import('node:fs/promises');
  const crypto = await import('node:crypto');
  const passage = await fs.readFile('game-night-note.md', 'utf8');
  const hash = crypto.createHash('sha256').update(passage, 'utf8').digest('hex');
  const task = {
    schemaVersion: '0.1',
    taskId: 'task-game-night-001',
    goal: '金曜のボードゲーム会に友だちを誘う短いメッセージを作成する（場所・時間・持ち物を含む）',
    mode: 'explain',
    successCriteria: [
      '開催日時（金曜日 18:30-20:30）が明記されていること',
      '開催場所（14 Willow Lane の community room）が明記されていること',
      '持ち物（室内履き / indoor shoes）が明記されていること',
      '友人を誘う自然で簡潔なメッセージになっていること'
    ],
    evidence: [
      {
        id: 'evidence-game-night-note',
        kind: 'document',
        locator: 'game-night-note.md',
        sourceGroup: 'notice',
        retrievedAt: new Date().toISOString(),
        version: null,
        scope: 'friday-game-night',
        passage: passage,
        contentHash: hash,
        validity: 'current'
      }
    ],
    reflectionRequired: true,
    proposedAnswer: '今週金曜（18:30〜20:30）に、14 Willow Laneのコミュニティルームでボードゲーム会があるんだけど、一緒に行かない？室内履き（上履き）だけ持ってくればOKで、お茶とお菓子も用意されてるよ（予約不要）。',
    capabilities: [],
    budget: {
      maxRounds: 5,
      maxModelCalls: 10,
      maxToolCalls: 10,
      maxElapsedMs: 300000,
      maxInputChars: 100000,
      maxOutputTokensPerCall: 4000
    }
  };
  const parsed = sdk.taskPacketSchema.parse(task);
  await fs.writeFile('.session/task.json', JSON.stringify(parsed, null, 2), 'utf8');
  console.log('task.json valid and written');
}).catch(err => { console.error(err); process.exit(1); });
